def git(*a, env=None):
    return subprocess.run(["git", *a], capture_output=True, text=True, env=env)

def blob(path):
    # git's own hash of the file as it would be committed, so a checkout with
    # Windows line endings (core.autocrlf) hashes the same as it does on GitHub.
    r = git("hash-object", "--", path)
    if r.returncode:
        raise FileNotFoundError(path)
    return r.stdout.strip()

def main():
    check = "--check" in sys.argv[1:]
    top = git("rev-parse", "--show-toplevel")
    if top.returncode or os.path.realpath(top.stdout.strip()) != os.path.realpath(os.getcwd()):
        sys.exit("REFUSED: run this from the root of the rnv-color-mcp repository.")
    if git("diff", "--cached", "--quiet").returncode:
        sys.exit("REFUSED: something is already staged. Commit or unstage it first.")
    plan, refused = [], []
    for path, f in FILES.items():
        if not os.path.isfile(path):
            refused.append(f"{path}: missing"); continue
        have = blob(path)
        if have == f["new"]:
            plan.append((path, "already")); continue
        if have != f["base"]:
            refused.append(f"{path}: blob {have[:8]}, expected {f['base'][:8]} (before) or {f['new'][:8]} (already applied)")
            continue
        plan.append((path, "replace"))
    if refused:
        print("REFUSED: nothing was written. What was found:")
        for r in refused: print("  " + r)
        sys.exit(1)
    for path, what in plan:
        print(f"  {what:8} {path}")
    if check:
        print("--check: nothing written."); return
    for path, what in plan:
        if what == "replace":
            data = FILES[path]["content"].encode("utf-8")
            # Keep the line endings of the file being replaced. A Windows
            # checkout with core.autocrlf=true holds CRLF; git stores LF either
            # way, so the blob is the same, and with core.safecrlf=true git
            # refuses to add an LF file it would convert.
            with open(path, "rb") as fh:
                if b"\r\n" in fh.read():
                    data = data.replace(b"\n", b"\r\n")
            with open(path, "wb") as fh:
                fh.write(data)
    bad = [p for p, f in FILES.items() if blob(p) != f["new"]]
    if bad:
        sys.exit("FAILED: written bytes do not match the tested blobs: " + ", ".join(bad))
    print(f"OK: all {len(FILES)} files match the tested blobs.")
    head_tree = git("rev-parse", "HEAD^{tree}").stdout.strip()
    if head_tree != BASE_TREE:
        print(f"Tree not checked: HEAD's tree is {head_tree[:8]}, not {BASE_TREE[:8]}. The per-file check above stands.")
        return
    with tempfile.TemporaryDirectory() as d:
        env = dict(os.environ, GIT_INDEX_FILE=os.path.join(d, "index"))
        steps = [("read-tree", "HEAD")] + [("add", "--", p) for p in FILES] + [("write-tree",)]
        for step in steps:
            r = git(*step, env=env)
            if r.returncode:
                sys.exit(f"FAILED: git {' '.join(step)} could not run, so the tree was not checked "
                         f"(the files above are written and match the tested blobs):\n{r.stderr.strip()}")
        tree = r.stdout.strip()
    if tree != EXPECTED_TREE:
        sys.exit(f"FAILED: tree {tree[:8]}, expected {EXPECTED_TREE[:8]}.")
    print(f"OK: the tree is {tree[:8]}, the tested tree. Git's index was not touched.")

main()
